from pathlib import Path
p=Path('app/src/main/java/com/tufanprintops/uretimperformans/MainActivity.java')
s=p.read_text(encoding='utf-8')

# Imports for an attached off-screen print WebView.
if 'import android.widget.FrameLayout;' not in s:
    s=s.replace('import android.webkit.WebViewClient;\n', 'import android.webkit.WebViewClient;\nimport android.widget.FrameLayout;\nimport android.view.ViewGroup;\n')

# Keep a root container so the dedicated print WebView is attached to the Activity.
old_fields='''    private WebView webView;\n    private WebView printWebView;\n'''
new_fields='''    private FrameLayout rootLayout;\n    private WebView webView;\n    private WebView printWebView;\n'''
if old_fields in s:
    s=s.replace(old_fields,new_fields,1)
elif 'private FrameLayout rootLayout;' not in s:
    raise SystemExit('WebView field block not found')

old_oncreate='''        webView = new WebView(this);\n        setContentView(webView);\n        configureWebView();\n        loadEmbeddedApp();'''
new_oncreate='''        rootLayout = new FrameLayout(this);\n        webView = new WebView(this);\n        rootLayout.addView(webView, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));\n        setContentView(rootLayout);\n        configureWebView();\n        loadEmbeddedApp();'''
if old_oncreate in s:
    s=s.replace(old_oncreate,new_oncreate,1)
elif 'rootLayout = new FrameLayout(this);' not in s:
    raise SystemExit('onCreate layout block not found')

old='''        @JavascriptInterface\n        public void printHtml(String title, String html) {\n            runOnUiThread(() -> {\n                try {\n                    if (printWebView != null) {\n                        try { printWebView.stopLoading(); printWebView.destroy(); } catch (Exception ignored) {}\n                        printWebView = null;\n                    }\n                    final WebView pv = new WebView(MainActivity.this);\n                    printWebView = pv;\n                    WebSettings ps = pv.getSettings();\n                    ps.setJavaScriptEnabled(false);\n                    ps.setDomStorageEnabled(false);\n                    ps.setLoadWithOverviewMode(true);\n                    ps.setUseWideViewPort(true);\n                    pv.setWebViewClient(new WebViewClient() {\n                        private boolean printRequested = false;\n                        @Override public void onPageFinished(WebView view, String url) {\n                            if (printRequested || printWebView != view) return;\n                            printRequested = true;\n                            view.postDelayed(() -> {\n                                try {\n                                    PrintManager pm = (PrintManager) getSystemService(Context.PRINT_SERVICE);\n                                    if (pm == null) throw new IllegalStateException("Android yazdırma servisi bulunamadı");\n                                    String job = (title == null || title.trim().isEmpty()) ? "Üretim Raporu" : title.trim();\n                                    pm.print(job, view.createPrintDocumentAdapter(job), null);\n                                    if (webView != null) webView.post(() -> webView.evaluateJavascript("if(window.nativePrintStarted){nativePrintStarted();}", null));\n                                } catch (Exception ex) {\n                                    final String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n                                    if (webView != null) webView.post(() -> webView.evaluateJavascript("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}", null));\n                                }\n                            }, 450);\n                        }\n                    });\n                    String safeHtml = (html == null || html.trim().isEmpty()) ? "<html><body><h2>Rapor içeriği boş.</h2></body></html>" : html;\n                    pv.loadDataWithBaseURL("https://print.local/", safeHtml, "text/html", "UTF-8", null);\n                } catch (Exception ex) {\n                    final String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n                    if (webView != null) webView.post(() -> webView.evaluateJavascript("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}", null));\n                }\n            });\n        }\n'''

new='''        @JavascriptInterface\n        public boolean printHtml(String title, String html) {\n            final String jobTitle = (title == null || title.trim().isEmpty()) ? "Üretim Raporu" : title.trim();\n            final String safeHtml = (html == null || html.trim().isEmpty()) ? "<html><body><h2>Rapor içeriği boş.</h2></body></html>" : html;\n            runOnUiThread(() -> {\n                try {\n                    if (webView != null) {\n                        webView.evaluateJavascript("if(window.nativePrintPreparing){nativePrintPreparing();}", null);\n                    }\n                    if (printWebView != null) {\n                        try {\n                            if (rootLayout != null) rootLayout.removeView(printWebView);\n                            printWebView.stopLoading();\n                            printWebView.destroy();\n                        } catch (Exception ignored) {}\n                        printWebView = null;\n                    }\n\n                    final WebView pv = new WebView(MainActivity.this);\n                    printWebView = pv;\n                    pv.setBackgroundColor(Color.WHITE);\n                    WebSettings ps = pv.getSettings();\n                    ps.setJavaScriptEnabled(false);\n                    ps.setDomStorageEnabled(false);\n                    ps.setLoadWithOverviewMode(true);\n                    ps.setUseWideViewPort(true);\n                    ps.setOffscreenPreRaster(true);\n\n                    if (rootLayout == null) throw new IllegalStateException("Yazdırma görünüm kapsayıcısı hazır değil");\n                    FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(\n                            ViewGroup.LayoutParams.MATCH_PARENT,\n                            ViewGroup.LayoutParams.MATCH_PARENT);\n                    // Attach behind the visible app WebView. Some OEM WebViews do not render an unattached print WebView.\n                    rootLayout.addView(pv, 0, lp);\n\n                    final boolean[] printRequested = {false};\n                    final Runnable startPrint = () -> {\n                        if (printRequested[0] || printWebView != pv || isFinishing()) return;\n                        printRequested[0] = true;\n                        try {\n                            PrintManager pm = (PrintManager) getSystemService(Context.PRINT_SERVICE);\n                            if (pm == null) throw new IllegalStateException("Android yazdırma servisi bulunamadı");\n                            pm.print(jobTitle, pv.createPrintDocumentAdapter(jobTitle), null);\n                            if (webView != null) {\n                                webView.evaluateJavascript("if(window.nativePrintStarted){nativePrintStarted();}", null);\n                            }\n                        } catch (Exception ex) {\n                            final String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n                            if (webView != null) {\n                                webView.evaluateJavascript("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}", null);\n                            }\n                        }\n                    };\n\n                    pv.setWebViewClient(new WebViewClient() {\n                        @Override public void onPageCommitVisible(WebView view, String url) {\n                            view.postDelayed(startPrint, 120);\n                        }\n                        @Override public void onPageFinished(WebView view, String url) {\n                            view.postDelayed(startPrint, 120);\n                        }\n                    });\n\n                    pv.loadDataWithBaseURL("https://print.local/", safeHtml, "text/html", "UTF-8", null);\n                    // OEM fallback: do not depend exclusively on WebView callbacks.\n                    pv.postDelayed(startPrint, 1200);\n                    pv.postDelayed(() -> {\n                        if (!printRequested[0] && printWebView == pv && webView != null) {\n                            webView.evaluateJavascript("if(window.nativePrintFailed){nativePrintFailed('Yazdırma görünümü hazırlanamadı.');}", null);\n                        }\n                    }, 3500);\n                } catch (Exception ex) {\n                    final String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n                    if (webView != null) {\n                        webView.evaluateJavascript("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}", null);\n                    }\n                }\n            });\n            return true;\n        }\n'''

if old not in s:
    raise SystemExit('exact v1.5 printHtml block not found')
s=s.replace(old,new,1)

p.write_text(s,encoding='utf-8')
print('patched-main-v152')
